// ── 앱 전체 UI 다국어 지원 ────────────────────────────────────────
// 네이티브 메뉴바(Rust labels())와 별개로, Svelte가 그리는 화면 텍스트를 담당한다.
// 메뉴바와 언어가 어긋나지 않도록 detectSystemLang()는 Rust의 detect_lang()과
// 같은 규칙을 쓴다.

export const LANGS = ['en', 'ko', 'es', 'ja', 'zh-hans', 'zh-hant'];

export const LANG_NAMES = {
  ko: '한국어',
  en: 'English',
  ja: '日本語',
  'zh-hans': '简体中文',
  'zh-hant': '繁體中文',
  es: 'Español',
};

const LANG_KEY = 'vimong-lang';

export function loadLangPref() {
  try { return localStorage.getItem(LANG_KEY) || 'auto'; } catch (_) { return 'auto'; }
}

export function saveLangPref(pref) {
  try { localStorage.setItem(LANG_KEY, pref); } catch (_) { /* skip */ }
}

export function detectSystemLang() {
  const locale = (typeof navigator !== 'undefined' ? navigator.language : '') || 'en';
  const l = locale.toLowerCase();
  if (l.startsWith('ko')) return 'ko';
  if (l.startsWith('ja')) return 'ja';
  if (l.startsWith('zh-hans') || l.startsWith('zh-cn') || l.startsWith('zh-sg')) return 'zh-hans';
  if (l.startsWith('zh')) return 'zh-hant';
  if (l.startsWith('es')) return 'es';
  return 'en';
}

