  'shortcuts.file.export': { ko: '이미지(PNG/JPG)나 PDF로 내보내기. pagespec 없으면 선택한 페이지, 없으면 현재 페이지(PDF는 전체). 여러 페이지를 지정하면 페이지마다 별도 파일로 저장되고, -m을 붙이면 파일 하나로 합쳐짐. -p로 암호 설정(PDF 전용)', en: 'Export as image (PNG/JPG) or PDF. Without pagespec, uses selected pages, or the current page (whole document for PDF). Multiple pages save as separate files unless -m combines them into one. -p sets a password (PDF only)', ja: '画像(PNG/JPG)またはPDFで書き出し。pagespec省略時は選択したページ、なければ現在のページ(PDFは全体)。複数ページ指定時はページごとに別ファイル、-mを付けると1つに結合。-pでパスワード設定(PDF専用)', 'zh-hans': '导出为图片(PNG/JPG)或PDF。省略pagespec时使用已选页面，否则为当前页(PDF为整个文档)。指定多个页面时每页单独保存，加 -m 则合并为一个文件。-p 设置密码(仅限 PDF)', 'zh-hant': '匯出為圖片(PNG/JPG)或PDF。省略pagespec時使用已選頁面，否則為目前頁面(PDF為整份文件)。指定多個頁面時每頁單獨儲存，加 -m 則合併為一個檔案。-p 設定密碼(僅限 PDF)', es: 'Exportar como imagen (PNG/JPG) o PDF. Sin pagespec, usa las páginas seleccionadas o la página actual (documento completo para PDF). Varias páginas se guardan por separado salvo que -m las combine en un archivo. -p establece una contraseña (solo PDF)' },
  'shortcuts.file.dd_key': { ko: 'dd (시작 화면)', en: 'dd (start screen)', ja: 'dd (スタート画面)', 'zh-hans': 'dd (启动画面)', 'zh-hant': 'dd (啟動畫面)', es: 'dd (pantalla de inicio)' },
  'shortcuts.file.dd_desc': { ko: '선택한 최근 파일을 목록에서 삭제', en: 'Remove the selected recent file from the list', ja: '選択した最近使ったファイルをリストから削除', 'zh-hans': '从列表中删除选中的最近文件', 'zh-hant': '從清單中刪除選取的最近檔案', es: 'Quitar de la lista el archivo reciente seleccionado' },
