  'shortcuts.search.regex_suffix': { ko: '검색어 끝에 붙이면 정규식 강제/해제 (.* 토글보다 우선)', en: 'Append to search term to force regex on/off (overrides the .* toggle)', ja: '検索語の末尾に付けると正規表現を強制的にオン/オフ (.*トグルより優先)', 'zh-hans': '加在搜索词末尾可强制启用/禁用正则 (优先于 .* 开关)', 'zh-hant': '加在搜尋詞結尾可強制啟用/停用正規表示式 (優先於 .* 切換)', es: 'Añade al final de la búsqueda para forzar/desactivar la expresión regular (tiene prioridad sobre el interruptor .*)' },
  'shortcuts.search.regex_toggle': { ko: '검색 탭의 정규식 토글 (vim magic 모드 문법, 룩어라운드·역참조는 미지원)', en: 'Regex toggle in the search tab (vim magic-mode syntax; lookaround/backreferences unsupported)', ja: '検索タブの正規表現トグル (vim magicモード構文。先読み・後読み・後方参照は非対応)', 'zh-hans': '搜索标签中的正则开关 (vim magic 模式语法，不支持环视和反向引用)', 'zh-hant': '搜尋標籤中的正規表示式切換 (vim magic 模式語法，不支援環視與反向參照)', es: 'Interruptor de expresión regular en la pestaña de búsqueda (sintaxis de modo magic de vim; no admite lookaround ni referencias inversas)' },
  'shortcuts.regex_syntax_title': { ko: '지원 정규식 문법 (vim magic 모드)', en: 'Supported regex syntax (vim magic mode)', ja: '対応する正規表現構文 (vim magicモード)', 'zh-hans': '支持的正则语法 (vim magic 模式)', 'zh-hant': '支援的正規表示式語法 (vim magic 模式)', es: 'Sintaxis de expresión regular admitida (modo magic de vim)' },
