export function t(lang, key, vars) {
  const entry = DICT[key];
  let s = entry ? (entry[lang] ?? entry.ko) : key;
  if (vars) for (const k in vars) s = s.replaceAll(`{${k}}`, vars[k]);
  return s;
}
